        match port.write_all(output) {
            Ok(_) => println!("Mensaje enviado al Arduino Mega via UART"),
            Err(ref e) if e.kind() == io::ErrorKind::TimedOut => (),
            Err(e) => eprintln!("{:?}", e),
        }
        std::thread::sleep(Duration::from_secs(5));
    }
