// Version: v1.0
//! # Driver para el sensor ultrasónico HC-SR04.
//!
//! Este driver permite medir distancias utilizando el sensor ultrasónico HC-SR04.
//! El funcionamiento se basa en enviar un pulso sónico y medir el tiempo que tarda
//! el eco en regresar al sensor.

use arduino_hal::port::Pin;
use arduino_hal::port::mode::{Input, Output, AnyInput};
use crate::sensors::ProximitySensor;

/// Estructura para el sensor ultrasónico HC-SR04.
/// 
/// Posee un pin de Trigger (disparador) y un pin de Echo (receptor).
pub struct HCSR04<TPIN, EPIN> {
    /// Pin de salida para iniciar la ráfaga ultrasónica.
    trigger: Pin<Output, TPIN>,
    /// Pin de entrada para medir la duración del pulso de retorno.
    echo: Pin<Input<AnyInput>, EPIN>,
}

impl<TPIN, EPIN> HCSR04<TPIN, EPIN>
where
    TPIN: arduino_hal::port::PinOps,
    EPIN: arduino_hal::port::PinOps,
{
    /// Crea una nueva instancia del sensor HC-SR04.
    ///
    /// # Parámetros
    /// * `trigger`: Pin configurado como salida (Output).
    /// * `echo`: Pin configurado como entrada genérica (Input<AnyInput>).
    pub fn new(trigger: Pin<Output, TPIN>, echo: Pin<Input<AnyInput>, EPIN>) -> Self {
        Self { trigger, echo }
    }

    /// Realiza una medición de distancia enviando un pulso.
    /// 
    /// Retorna la distancia calculada en milímetros (mm).
    /// Retorna `None` si la lectura excede el tiempo de espera (timeout)
    /// o si la distancia está fuera del rango operativo del sensor (aprox. 4m).
    pub fn measure_mm(&mut self) -> Option<u16> {
        // Aseguramos que el trigger esté en BAJO antes de iniciar el ciclo.
        self.trigger.set_low();
        arduino_hal::delay_us(2);

        // Enviamos el pulso de disparo (mínimo 10 microsegundos).
        self.trigger.set_high();
        arduino_hal::delay_us(10);
        self.trigger.set_low();

        // Esperamos a que el pin Echo suba a ALTO (inicio del retorno).
        // Se utiliza un contador simple para implementar un timeout.
        let mut count = 0;
        while self.echo.is_low() {
            count += 1;
            if count > 20000 { return None; } 
        }

        // Medimos cuánto tiempo permanece el pin Echo en ALTO.
        // La duración es proporcional a la distancia recorrida por el sonido.
        let mut duration_us: u32 = 0;
        while self.echo.is_high() {
            duration_us += 1;
            arduino_hal::delay_us(1);
            // Timeout preventivo si no hay objeto cercano o error (max ~5.1 metros).
            if duration_us > 30000 { return None; }
        }

        // Cálculo de distancia: (Tiempo * Velocidad del Sonido) / 2
        // Velocidad del sonido aprox. 0.343 mm/µs.
        // Formula: (duration_us * 1715) / 10000 es equivalente a (dur * 0.1715).
        let distance = (duration_us * 1715) / 10000;

        // El rango práctico del HC-SR04 es de 2cm a 400cm.
        if distance > 4000 || distance < 2 {
            None
        } else {
            Some(distance as u16)
        }
    }
}

impl<TPIN, EPIN> ProximitySensor for HCSR04<TPIN, EPIN>
where
    TPIN: arduino_hal::port::PinOps,
    EPIN: arduino_hal::port::PinOps,
{
    /// Implementación de la interfaz común para obtener la distancia.
    fn get_distance_mm(&mut self) -> Option<u16> {
        self.measure_mm()
    }
}

// Version: v1.0
//! # Driver para el sensor LiDAR de corto rango TF-Luna.
//!
//! Este driver permite la comunicación serie con el sensor LiDAR TF-Luna de Benewake.
//! El sensor envía paquetes de 9 bytes de forma continua con datos de distancia,
//! intensidad de señal y temperatura.

use arduino_hal::hal::usart::Usart;
use arduino_hal::prelude::*;
use crate::sensors::ProximitySensor;

/// Estructura para el sensor LiDAR TF-Luna.
/// 
/// Encapsula un puerto UART (USART) del ATmega2560 para la lectura de datos.
pub struct TFLuna<USART, RX, TX, CLOCK>
where
    USART: arduino_hal::hal::usart::UsartOps<arduino_hal::hal::Atmega, RX, TX>,
{
    /// Periférico serie utilizado para recibir los frames del sensor.
    serial: Usart<USART, RX, TX, CLOCK>,
}

impl<USART, RX, TX, CLOCK> TFLuna<USART, RX, TX, CLOCK>
where
    USART: arduino_hal::hal::usart::UsartOps<arduino_hal::hal::Atmega, RX, TX>,
    CLOCK: arduino_hal::hal::clock::Clock,
{
    /// Crea una nueva instancia del sensor TF-Luna.
    ///
    /// # Parámetros
    /// * `serial`: Una instancia de USART configurada a 115200 baudios.
    pub fn new(serial: Usart<USART, RX, TX, CLOCK>) -> Self {
        Self { serial }
    }

    /// Intenta leer un paquete de datos completo del sensor.
    /// 
    /// Formato del frame (9 bytes):
    /// [0x59, 0x59, Dist_L, Dist_H, Strength_L, Strength_H, Temp_L, Temp_H, Checksum]
    /// 
    /// Retorna la distancia en milímetros (mm).
    pub fn read_packet(&mut self) -> Option<u16> {
        let mut header_count = 0;
        let mut timeout = 0;

        // Fase 1: Sincronización con la cabecera del frame (0x59 0x59).
        while header_count < 2 {
            if let Ok(byte) = self.serial.read() {
                if byte == 0x59 {
                    header_count += 1;
                } else {
                    header_count = 0;
                }
            }
            timeout += 1;
            if timeout > 2000 { return None; }
        }

        // Fase 2: Lectura de los datos restantes (7 bytes).
        let mut data = [0u8; 7];
        let mut sum: u16 = 0x59 + 0x59; // La suma del checksum incluye la cabecera.

        for i in 0..7 {
            let mut sub_timeout = 0;
            loop {
                if let Ok(byte) = self.serial.read() {
                    data[i] = byte;
                    // Sumamos los primeros 8 bytes para validar el checksum posterior.
                    if i < 6 { sum += byte as u16; }
                    break;
                }
                sub_timeout += 1;
                if sub_timeout > 1000 { return None; }
            }
        }

        // Fase 3: Validación del Checksum (Byte 9).
        let checksum = data[6];
        if (sum & 0xFF) as u8 != checksum {
            return None; // Frame corrupto o error de transmisión.
        }

        // Fase 4: Interpretación de la distancia (Bytes 2 y 3).
        // El valor viene en centímetros (cm).
        let dist_cm = (data[1] as u16) << 8 | (data[0] as u16);

        // Convertimos a milímetros para consistencia con el Trait ProximitySensor.
        Some(dist_cm * 10)
    }
}

impl<USART, RX, TX, CLOCK> ProximitySensor for TFLuna<USART, RX, TX, CLOCK>
where
    USART: arduino_hal::hal::usart::UsartOps<arduino_hal::hal::Atmega, RX, TX>,
    CLOCK: arduino_hal::hal::clock::Clock,
{
    /// Obtiene la distancia actual del sensor LiDAR en mm.
    fn get_distance_mm(&mut self) -> Option<u16> {
        self.read_packet()
    }
}

