//! detección de atascos (anti-stall).

use crate::motor_control::Motor;
use crate::sensors::encoder::Encoder;

/// Estructura que representa un canal de tracción (Motor + Encoder).
pub struct DriveChannel<M: Motor, E: Encoder> {
    pub motor: M,
    pub encoder: E,
    last_count: i32,
    stall_timer: u16, // Contador de ciclos sin movimiento
}

impl<M: Motor, E: Encoder> DriveChannel<M, E> {
    pub fn new(motor: M, encoder: E) -> Self {
        Self {
            motor,
            encoder,
            last_count: 0,
            stall_timer: 0,
        }
    }

    /// Actualiza el estado del canal y detecta si está atascado.
    /// speed: Potencia actual enviada al motor (-100 a 100).
    /// Retorna true si se detecta un posible atasco (potencia > 0 pero sin pulsos).
    pub fn check_stall(&mut self, speed: i16) -> bool {
        let current_count = self.encoder.get_counts();
        let speed_abs = speed.abs();

        // Si hay potencia significativa (>20%) pero el encoder no se mueve
        if speed_abs > 20 && current_count == self.last_count {
            self.stall_timer = self.stall_timer.saturating_add(1);
        } else {
            self.stall_timer = 0;
        }

        self.last_count = current_count;

        // Si el timer llega a un umbral (ej. 50 ciclos de control), reportar atasco
        // A 20ms por ciclo, 50 ciclos = 1 segundo de motor bloqueado
        self.stall_timer > 50
    }
}

/// Controlador principal para un chasis de 6 ruedas independientes.
pub struct RoverController<M: Motor, E: Encoder> {
    pub channels: [DriveChannel<M, E>; 6],
    pub is_stalled: [bool; 6],
    pub emergency_stop: bool,
}

impl<M: Motor, E: Encoder> RoverController<M, E> {
    /// Crea un nuevo controlador con 6 canales.
    pub fn new(channels: [DriveChannel<M, E>; 6]) -> Self {
        Self {
            channels,
            is_stalled: [false; 6],
            emergency_stop: false,
        }
    }

    /// Control tipo "Tanque" (Diferencial).
    /// left_speed: Potencia para el lado izquierdo (Motores 0, 1, 2).
    /// right_speed: Potencia para el lado derecho (Motores 3, 4, 5).
    pub fn tank_drive(&mut self, left_speed: i16, right_speed: i16) {
        if self.emergency_stop { return; }

        // Lado izquierdo (0: Delantero Izq, 1: Medio Izq, 2: Trasero Izq)
        for i in 0..3 { self.channels[i].motor.set_speed(left_speed); }
        // Lado derecho (3: Delantero Der, 4: Medio Der, 5: Trasero Der)
        for i in 3..6 { self.channels[i].motor.set_speed(right_speed); }
    }

    /// Rutina de seguridad: Debe llamarse periódicamente (ej. cada 20ms).
    pub fn update(&mut self, current_speeds: [i16; 6]) {
        if self.emergency_stop { return; }

        let mut left_stalls: u8 = 0;
        let mut right_stalls: u8 = 0;

        for i in 0..6 {
            self.is_stalled[i] = self.channels[i].check_stall(current_speeds[i]);

            if self.is_stalled[i] {
                // Si una rueda está atascada, la detenemos individualmente para proteger el motor
                self.channels[i].motor.stop();

                if i < 3 { left_stalls += 1; } 
                else { right_stalls += 1; }
            }
        }

        // Política de seguridad global: Si 2 o más ruedas de un lado están atascadas, STOP total.
        if left_stalls >= 2 || right_stalls >= 2 {
            self.stop_all();
            self.emergency_stop = True; // Flag de parada de emergencia activa
        }
    }

    /// Detiene todos los motores inmediatamente.
    pub fn stop_all(&mut self) {
        for channel in &mut self.channels {
            channel.motor.stop();
        }
    }

    /// Reinicia el estado de parada de emergencia.
    pub fn reset_emergency(&mut self) {
        self.emergency_stop = false;
        for i in 0..6 { self.is_stalled[i] = false; }
    }
}

