// Version: v1.0
//! # Ejemplo de Prueba del Controlador Central
//!
//! Este ejemplo configura los 6 motores L298N y los 6 encoders para validar
//! la lógica de tracción y la detección de atascos.

#![no_std]
#![no_main]

use arduino_hal::prelude::*;
use panic_halt as _;
use rover_low_level_controller::motor_control::l298n::L298NMotor;
use rover_low_level_controller::sensors::encoder::HallEncoder;
use rover_low_level_controller::controller::{RoverController, DriveChannel};

#[arduino_hal::entry]
fn main() -> ! {
    let dp = arduino_hal::Peripherals::take().unwrap();
    let pins = arduino_hal::pins!(dp);
    let mut serial = arduino_hal::default_serial!(dp, pins, 115200);

    // Configuración de Timers para PWM (ATmega2560 tiene muchos canales)
    let timer2 = arduino_hal::simple_pwm::Timer2Pwm::new(dp.TIMER2, arduino_hal::simple_pwm::Prescaler::Prescale64);
    let timer3 = arduino_hal::simple_pwm::Timer3Pwm::new(dp.TIMER3, arduino_hal::simple_pwm::Prescaler::Prescale64);
    let timer4 = arduino_hal::simple_pwm::Timer4Pwm::new(dp.TIMER4, arduino_hal::simple_pwm::Prescaler::Prescale64);

    // --- CONFIGURACIÓN DE MOTORES (Ejemplo de asignación de pines) ---
    // En un sistema real, usaríamos los pines definidos en docs/the_pins_connections.md

    // Motor 0: Delantero Izquierda (Timer 2, Canal A -> D10)
    let m0 = L298NMotor::new(pins.d10.into_output().into_pwm(&timer2), pins.d22.into_output(), pins.d23.into_output(), false);
    let e0 = HallEncoder::new();

    // Motor 1: Medio Izquierda (Timer 2, Canal B -> D9)
    let m1 = L298NMotor::new(pins.d9.into_output().into_pwm(&timer2), pins.d24.into_output(), pins.d25.into_output(), false);
    let e1 = HallEncoder::new();

    // Motor 2: Trasero Izquierda (Timer 3, Canal A -> D5)
    let m2 = L298NMotor::new(pins.d5.into_output().into_pwm(&timer3), pins.d26.into_output(), pins.d27.into_output(), false);
    let e2 = HallEncoder::new();

    // Motor 3: Delantero Derecha (Timer 3, Canal B -> D2)
    let m3 = L298NMotor::new(pins.d2.into_output().into_pwm(&timer3), pins.d28.into_output(), pins.d29.into_output(), false);
    let e3 = HallEncoder::new();

    // Motor 4: Medio Derecha (Timer 4, Canal A -> D6)
    let m4 = L298NMotor::new(pins.d6.into_output().into_pwm(&timer4), pins.d30.into_output(), pins.d31.into_output(), false);
    let e4 = HallEncoder::new();

    // Motor 5: Trasero Derecha (Timer 4, Canal B -> D7)
    let m5 = L298NMotor::new(pins.d7.into_output().into_pwm(&timer4), pins.d32.into_output(), pins.d33.into_output(), false);
    let e5 = HallEncoder::new();

    // --- CREACIÓN DEL CONTROLADOR ---
    let channels = [
        DriveChannel::new(m0, e0),
        DriveChannel::new(m1, e1),
        DriveChannel::new(m2, e2),
        DriveChannel::new(m3, e3),
        DriveChannel::new(m4, e4),
        DriveChannel::new(m5, e5),
    ];

    let mut rover = RoverController::new(channels);

    ufmt::uwriteln!(&mut serial, "Controlador Rover de 6 Ruedas Iniciado.\r").void_unwrap();

    loop {
        // Simulación de comando: Avanzar lento (30% potencia)
        rover.tank_drive(30, 30);

        // El bucle de control debe ejecutarse con tiempo constante
        for _ in 0..10 {
            // En un sistema real, aquí llamaríamos a rover.update() con las velocidades actuales
            rover.update([30, 30, 30, 30, 30, 30]);

            if rover.emergency_stop {
                ufmt::uwriteln!(&mut serial, "¡PARADA DE EMERGENCIA! Sistema bloqueado.\r").void_unwrap();
                // En este punto, el rover no se moverá hasta un reset
            }

            arduino_hal::delay_ms(20); // Ciclo de control de 20ms (50Hz)
        }
    }
}

