    let m3 = L298NMotor::new(pins.d2.into_output().into_pwm(&timer3), pins.d28.into_output(), pins.d29.into_output(), false);
    let e3 = HallEncoder::new();

    // Motor 4: Medio Derecha (Timer 4, Canal A -> D6)
    let m4 = L298NMotor::new(pins.d6.into_output().into_pwm(&timer4), pins.d30.into_output(), pins.d31.into_output(), false);
    let e4 = HallEncoder::new();

    // Motor 5: Trasero Derecha (Timer 4, Canal B -> D7)
    let m5 = L298NMotor::new(pins.d7.into_output().into_pwm(&timer4), pins.d32.into_output(), pins.d33.into_output(), false);
    let e5 = HallEncoder::new();

    // --- CREACIÓN DEL CONTROLADOR ---
    let channels = [
        DriveChannel::new(m0, e0),
        DriveChannel::new(m1, e1),
        DriveChannel::new(m2, e2),
        DriveChannel::new(m3, e3),
        DriveChannel::new(m4, e4),
        DriveChannel::new(m5, e5),
    ];

    let mut rover = RoverController::new(channels);

    ufmt::uwriteln!(&mut serial, "Controlador Rover de 6 Ruedas Iniciado.\r").void_unwrap();

    loop {
        // Simulación de comando: Avanzar lento (30% potencia)
        rover.tank_drive(30, 30);

        // El bucle de control debe ejecutarse con tiempo constante
        for _ in 0..10 {
            // En un sistema real, aquí llamaríamos a rover.update() con las velocidades actuales
            rover.update([30, 30, 30, 30, 30, 30]);

            if rover.emergency_stop {
                ufmt::uwriteln!(&mut serial, "¡PARADA DE EMERGENCIA! Sistema bloqueado.\r").void_unwrap();
                // En este punto, el rover no se moverá hasta un reset
            }

            arduino_hal::delay_ms(20); // Ciclo de control de 20ms (50Hz)
        }
    }
}

